use crate::aap::caps::kb_read;

struct Node;

const MAX_QUESTION_CHARS: usize = 512;

/// Truncate to at most `max` Unicode scalar values, matching Python's `len`.
fn bound_chars(s: String, max: usize) -> String {
    match s.char_indices().nth(max) {
        Some((idx, _)) => s[..idx].to_string(),
        None => s,
    }
}

impl Guest for Node {
    fn run(query: ModeratedQuery) -> ConversationContext {
        let q = query.query;
        let question = bound_chars(q.question, MAX_QUESTION_CHARS);

        let mut knowledge: Vec<String> = Vec::new();

        if !question.is_empty() {
            for item in kb_read::lookup(&question) {
                if !knowledge.contains(&item) {
                    knowledge.push(item);
                }
            }
        }

        for entity in q.entities.iter() {
            if entity.is_empty() {
                continue;
            }
            for item in kb_read::lookup(entity) {
                if !knowledge.contains(&item) {
                    knowledge.push(item);
                }
            }
        }

        ConversationContext {
            intent: q.intent,
            question,
            knowledge,
        }
    }
}

export!(Node);
